  it('sourceRef 定式与 active 节点 id 同参：active:<phase>:<attempt> 与 <change>/<phase>/<role>/<attempt> 同 attempt 组装', async () => {
    sessionsFixture = {
      'test-change/implement/executor/2': [
        transcriptSession('ses-exec-2', 'test-change/implement/executor/2'),
